            ["editor.fix_chart_load_hint"] = "Dezactivat implicit. Este un set de patch-uri care rescriu comportamentul editorului pentru a corecta granularitatea editării Dalelor/Evenimentelor; când este activ, editorul se comportă vizibil diferit de original. Când este dezactivat, editarea Dalelor/Evenimentelor și granularitatea anulării revin la comportamentul original.",
            ["perf.footnote"] = "注：实际挂载数还要过版本门控与目标解析，通常少于上表。PACL2 的补丁不计入。",
            ["perf.footnote"] = "Note: the actually mounted count also passes version gating and target resolution, so it is usually lower. PACL2 patches are not included.",
            ["perf.footnote"] = "참고: 실제 적용 개수는 버전 게이트와 대상 해석을 추가로 거치므로 대개 더 적습니다. PACL2 패치는 포함되지 않습니다.",
            ["perf.footnote"] = "注：実際の適用数はバージョンゲートと対象解決を通るため、たいてい上の表より少なくなります。PACL2 のパッチは含みません。",
            ["perf.footnote"] = "註：實際掛載數還要過版本門控與目標解析，通常少於上表。PACL2 的補丁不計入。",
            ["perf.footnote"] = "Nota: el número realmente montado también pasa el control de versión y la resolución de destinos, así que suele ser menor. Los parches de PACL2 no se incluyen.",
            ["perf.footnote"] = "Nota: a contagem realmente montada também passa pelo controle de versão e resolução de alvos, então costuma ser menor. Patches do PACL2 não entram.",
            ["perf.footnote"] = "Remarque : le nombre réellement monté passe aussi par le contrôle de version et la résolution des cibles, il est donc généralement plus faible. Les correctifs PACL2 ne sont pas comptés.",
            ["perf.footnote"] = "Hinweis: Die tatsächlich montierte Anzahl durchläuft zusätzlich Versions-Gating und Zielauflösung und ist daher meist kleiner. PACL2-Patches sind nicht enthalten.",
            ["perf.footnote"] = "Uwaga: faktycznie zamontowana liczba przechodzi też przez bramkowanie wersji i rozwiązywanie celów, więc jest zwykle mniejsza. Poprawki PACL2 nie są wliczane.",
            ["perf.footnote"] = "Примечание: реально смонтированное число дополнительно проходит отбор по версии и разрешению целей, поэтому обычно меньше. Патчи PACL2 не учтены.",
            ["perf.footnote"] = "Notă: numărul montat efectiv trece și prin filtrarea de versiune și rezolvarea țintelor, deci de obicei este mai mic. Patch-urile PACL2 nu sunt incluse.",
            ["perf.footnote"] = "Lưu ý: số bản vá thực sự gắn còn phải qua cổng phiên bản và phân giải đích nên thường ít hơn bảng trên. Bản vá của PACL2 không được tính.",
            ["perf.footnote"] = "Poznámka: skutečně zamontovaný počet prochází také verzní bránou a rozlišením cílů, takže je obvykle menší. Opravy PACL2 nejsou započteny.",
            ["perf.head"] = "本程序集补丁声明总数：",
            ["perf.head"] = "Patches declared in this assembly:",
            ["perf.head"] = "이 어셈블리에 선언된 패치 수:",
            ["perf.head"] = "このアセンブリで宣言されたパッチ数：",
            ["perf.head"] = "本程式組補丁宣告總數：",
            ["perf.head"] = "Parches declarados en este ensamblado:",
            ["perf.head"] = "Patches declarados neste assembly:",
            ["perf.head"] = "Correctifs déclarés dans cet assembly :",
            ["perf.head"] = "In dieser Assembly deklarierte Patches:",
            ["perf.head"] = "Poprawki zadeklarowane w tym zestawie:",
            ["perf.head"] = "Патчей объявлено в этой сборке:",
            ["perf.head"] = "Patch-uri declarate în acest assembly:",
            ["perf.head"] = "Số bản vá được khai báo trong assembly này:",
            ["perf.head"] = "Oprav deklarovaných v tomto sestavení:",
            ["perf.intro"] = "每个功能开关背后都挂着若干条 IL 补丁，这些成本此前完全不可见。下面按条数从多到少列出，用来判断关掉哪个最划算——要关请到对应页面操作。",
            ["perf.intro"] = "Each feature toggle carries a number of IL patches, and that cost was previously invisible. Listed below, most expensive first, so you can tell which one is worth turning off. To turn something off, go to its own page.",
            ["perf.intro"] = "각 기능 스위치 뒤에는 여러 IL 패치가 붙어 있는데 이 비용은 이전까지 보이지 않았습니다. 패치 수가 많은 순으로 나열했으니 어느 항목을 끄는 것이 이득인지 판단할 수 있습니다. 끄려면 해당 페이지로 가세요.",
            ["perf.intro"] = "各機能スイッチの裏には複数の IL パッチが付いています。このコストはこれまで可視化されていません。パッチ数の多い順に並べたので、どの機能を切るのが得当か判断できます。OFF にするには各機能のページへ移動します。",
            ["perf.intro"] = "每個功能開關背後都掛著若干條 IL 補丁，這些成本此前完全不可見。下面按條數從多到少列出，用來判斷關掉哪個最划算——要關請到對應頁面操作。",
            ["perf.intro"] = "Cada interruptor de función lleva varios parches IL, y ese coste no era visible hasta ahora. Se listan de mayor a menor para que se vea cuál conviene desactivar. Para desactivar algo, ve a su propia página.",
            ["perf.intro"] = "Cada interruptor de recurso traz vários patches IL, e esse custo nunca foi visível. Listados do maior para o menor, para ver qual vale a pena desativar. Para desativar, vá até a página do próprio recurso.",
            ["perf.intro"] = "Chaque interrupteur de fonctionnalité embarque plusieurs correctifs IL, et ce coût n était pas visible jusqu ici. Ils sont listés du plus coûteux au moins coûteux, pour voir lequel il vaut la peine de désactiver. Pour désactiver, allez dans la page correspondante.",
            ["perf.intro"] = "Jeder Feature-Schalter trägt eine Anzahl IL-Patches, deren Kosten bisher unsichtbar waren. Aufgelistet von teuer nach günstig, damit erkennbar ist, was sich lohnt abzuschalten. Zum Abschalten bitte die jeweilige Seite öffnen.",
            ["perf.intro"] = "Każdy przełącznik funkcji niesie pewną liczbę poprawek IL, a ten koszt był dotąd niewidoczny. Wypisano od najdroższego do najtańszego, by widać było, co warto wyłączyć. Aby wyłączyć, przejdź do jego strony.",
            ["perf.intro"] = "За каждым переключателем функции стоит несколько IL-патчей, и эта стоимость до сих пор была не видна. Список от большего к меньшему — видно, что выгоднее отключить. Чтобы отключить, откройте соответствующую страницу.",
            ["perf.intro"] = "Fiecare comutator de funcție aduce mai multe patch-uri IL, iar acest cost nu era vizibil până acum. Sunt listate de la cel mai mare la cel mai mic, ca să se vadă ce merită oprit. Pentru a opri, mergi pe pagina funcției respective.",
            ["perf.intro"] = "Mỗi công tắc tính năng đều kéo theo vài bản vá IL, và chi phí đó trước đây không hiển thị. Danh sách sắp theo số bản vá giảm dần, để biết cái nào đáng tắt. Muốn tắt thì hãy vào trang của tính năng đó.",
            ["perf.intro"] = "Každý přepínač funkce nese několik IL oprav a tato cena dosud nebyla vidět. Seznam je sestupně podle počtu oprav, abyste viděli, co se vyplatí vypnout. Vypíná se na příslušné stránce.",
