            ["rendervideo.output"] = "Dosar de ieșire",
            ["rendervideo.note"] = "Randare offline cadru cu cadru: număr constant de cadre pe secundă în rezultat, indiferent de performanța mașinii. Captura poate fi camera curată (fără UI de ecran, orice rezoluție) sau imaginea jocului (cu UI, rezoluția ferestrei; restrânge fereastra modului în timpul randării). Încarcă un replay și intră în nivelul lui înainte de start; timpul depinde de mașină, nu atinge jocul în timpul randării și ține fereastra în prim-plan cu motorul moștenit de taste. Necesită ffmpeg (în dosarul modului sau rădăcina jocului).",
