            ["rendervideo.output"] = "Dossier de sortie",
            ["rendervideo.note"] = "Rendu hors ligne image par image : fréquence d'images constante, indépendante des performances de la machine. La capture est soit la caméra pure (sans UI écran, toute résolution), soit la vue du jeu (avec UI, résolution selon la fenêtre ; réduisez la fenêtre du mod pendant le rendu). Chargez un replay et entrez dans son niveau avant de lancer ; la durée dépend de votre machine, ne touchez pas au jeu pendant le rendu et gardez la fenêtre au premier plan avec l'ancien moteur de touches. Nécessite ffmpeg (dossier du mod ou racine du jeu).",
