    internal static string currentLanguage = "en";

    internal static Dictionary<SystemLanguage, string> langlist = new()
    {
        { (SystemLanguage)10, "en" },
        { (SystemLanguage)23, "ko" },
        { (SystemLanguage)40, "zh" },
        { (SystemLanguage)41, "zh-t" },
        { (SystemLanguage)34, "es" },
        { (SystemLanguage)28, "pt" },
        { (SystemLanguage)22, "ja" },
        { (SystemLanguage)27, "pl" },
        { (SystemLanguage)30, "ru" },
        { (SystemLanguage)29, "ro" },
        { (SystemLanguage)39, "vi" },
        { (SystemLanguage)14, "fr" },
        { (SystemLanguage)7, "cs" },
        { (SystemLanguage)15, "de" }
    };

    internal static Dictionary<string, SystemLanguage> langCodeToLanguage = new()
    {
        { "en", (SystemLanguage)10 }, { "ko", (SystemLanguage)23 }, { "zh", (SystemLanguage)40 },
        { "zh-t", (SystemLanguage)41 }, { "es", (SystemLanguage)34 }, { "pt", (SystemLanguage)28 },
        { "ja", (SystemLanguage)22 }, { "pl", (SystemLanguage)27 }, { "ru", (SystemLanguage)30 },
        { "ro", (SystemLanguage)29 }, { "vi", (SystemLanguage)39 }, { "fr", (SystemLanguage)14 },
        { "cs", (SystemLanguage)7 }, { "de", (SystemLanguage)15 }
    };

    internal static Dictionary<string, SystemLanguage> langCodeToGoogleDocCode = new()
    {
        { "en", (SystemLanguage)10 }, { "ko", (SystemLanguage)23 }, { "zh", (SystemLanguage)40 },
        { "zh-t", (SystemLanguage)41 }, { "es", (SystemLanguage)34 }, { "pt", (SystemLanguage)28 },
        { "ja", (SystemLanguage)22 }, { "pl", (SystemLanguage)27 }, { "ru", (SystemLanguage)30 },
        { "ro", (SystemLanguage)29 }, { "vi", (SystemLanguage)39 }, { "fr", (SystemLanguage)14 },
        { "cs", (SystemLanguage)7 }, { "de", (SystemLanguage)15 }
    };

    internal static string GetLangCode(SystemLanguage lang)
    {
        return langlist.TryGetValue(lang, out var code) ? code : "en";
    }

    internal static SystemLanguage CodeToLang(string code)
    {
        return langCodeToLanguage.TryGetValue(code, out var lang) ? lang : (SystemLanguage)10;
    }

    internal static SystemLanguage CodeToGoogleDocCode(string code)
    {
        return langCodeToGoogleDocCode.TryGetValue(code, out var lang) ? lang : (SystemLanguage)10;
    }

    internal static void GetLanguages()
    {
        if (langlist.TryGetValue(RDString.language, out var code))
            currentLanguage = code;
    }

    internal static string GetLocalizedText(string key, string lang = null)
    {
        // 跟随游戏语言时每次取词都同步：mod 加载早于游戏应用用户语言设置（日志里
        // Spectre 先 Active、后 setting language），开局路径上又没有 checklang 时机，
        // "不开设置窗口直接玩到结算"会拿到过期的启动默认语言（英文）
        if (lang == null && Settings.FollowGameLanguage)
            GetLanguages();
        lang ??= currentLanguage;
        if (languageData.TryGetValue(lang, out var dict) && dict.TryGetValue(key, out var val))
            return val;
        if (lang != "en" && languageData.TryGetValue("en", out var enDict) && enDict.TryGetValue(key, out var enVal))
            return enVal;
        return key;
    }

    internal static void SwitchLanguage(string langCode)
    {
        if (languageData.ContainsKey(langCode))
        {
            currentLanguage = langCode;
            Debug.Log(("Language switched to " + langCode + "."));
        }
    }
}
